 runs[arm]=dict(path=str(folder.relative_to(root)),last_checkpoint=last,completed_episodes=len(rows),time_limit_truncations=sum(x['truncated'] for x in rows),explicit_finite_ends=sum(x.get('finite_horizon_end',False) for x in rows),native_deaths=sum(x.get('native_game_over',not x['truncated']) for x in rows),training_score_mean=sum(x['r'] for x in rows)/len(rows),rollout_metrics=metrics)
